const sqlText=value=>value==null?'NULL':`'${String(value).replaceAll("'","''")}'`;
const sqlNumber=value=>value==null||Number.isNaN(Number(value))?'NULL':String(Number(value));
const slug=value=>String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const seriesId=book=>book.series_id?`audible-series-${book.series_id}`:null;
const authorRows=book=>Array.isArray(book.authors)&&book.authors.length?book.authors:[{name:book.author,id:book.author_id,url:book.author_url}].filter(row=>row.name);
const authorId=author=>author.id?`audible-author-${author.id}`:`audible-author-${slug(author.name)}`;
const narratorId=name=>`audible-narrator-${slug(name)}`;
const catalogMetadata=asin=>AUDIBLE_CATALOG_SNAPSHOT?.[String(asin||'').toUpperCase()]||null;
const asinCoverUrl=asin=>catalogMetadata(asin)?.sourceCoverImageUrl||catalogMetadata(asin)?.coverImageUrl||null;

export function buildAudibleSeedSql(){
  const statements=[];
  const seenSeries=new Set(),seenAuthors=new Set(),seenNarrators=new Set();
  for(const book of AUDIBLE_SEED_BOOKS){
    const now=AUDIBLE_SEED_CAPTURED_AT+'T12:00:00-04:00';
    if(book.series_id&&!seenSeries.has(book.series_id)){
      seenSeries.add(book.series_id);
      statements.push(`INSERT OR IGNORE INTO audible_series(series_id,audible_series_id,name,audible_url,total_known,source,created_at,updated_at,last_catalog_refresh_at) VALUES (${sqlText(seriesId(book))},${sqlText(book.series_id)},${sqlText(book.series_name)},${sqlText(book.series_url)},NULL,${sqlText(AUDIBLE_SEED_SOURCE)},${sqlText(now)},${sqlText(now)},NULL)`);
    }
    const authors=authorRows(book);
    for(const author of authors){
      const aid=authorId(author);
      if(!seenAuthors.has(aid)){
        seenAuthors.add(aid);
        statements.push(`INSERT OR IGNORE INTO audible_authors(author_id,audible_author_id,name,audible_url,created_at,updated_at) VALUES (${sqlText(aid)},${sqlText(author.id)},${sqlText(author.name)},${sqlText(author.url)},${sqlText(now)},${sqlText(now)})`);
      }
    }
    for(const narrator of book.narrators||[]){
      const nid=narratorId(narrator);
      if(!seenNarrators.has(nid)){
        seenNarrators.add(nid);
        statements.push(`INSERT OR IGNORE INTO audible_narrators(narrator_id,name,audible_url,created_at,updated_at) VALUES (${sqlText(nid)},${sqlText(narrator)},NULL,${sqlText(now)},${sqlText(now)})`);
      }
    }
    const bid=`audible-book-${book.asin}`;
    const catalog=catalogMetadata(book.asin);
    const cover=asinCoverUrl(book.asin);
    const capturedRuntime=Number(book.runtime_minutes)>0?Number(book.runtime_minutes):null;
    const catalogRuntime=Number(catalog?.runtimeMinutes)>0?Number(catalog.runtimeMinutes):null;
    const runtime=capturedRuntime||catalogRuntime;
    const runtimeDisplay=book.runtime_display||(runtime?`${Math.floor(runtime/60)}h${runtime%60?` ${runtime%60}m`:''}`:null);
    const coverSource=cover?(String(cover).startsWith('http')?'audible-validated-remote':'audible-product-page-local-cache'):null;
    statements.push(`INSERT OR IGNORE INTO audible_audiobooks(audiobook_id,audible_asin,title,display_title,raw_title,audible_product_url,runtime_minutes,runtime_display,description,description_is_truncated,cover_image_url,cover_image_source,series_id,series_position,in_audible_library,owned_in_audible,ownership_status,audible_progress_text,remaining_minutes,listening_status,can_listen_now,discovered_from_series,source,first_imported_at,last_seen_at,last_metadata_refresh_at) VALUES (${sqlText(bid)},${sqlText(book.asin)},${sqlText(book.title)},${sqlText(book.title)},${sqlText(book.title)},${sqlText(book.product_url)},${sqlNumber(runtime)},${sqlText(runtimeDisplay)},${sqlText(book.description)},${book.description_is_truncated?1:0},${sqlText(cover)},${sqlText(coverSource)},${sqlText(seriesId(book))},${sqlNumber(book.series_position)},1,1,'owned',${sqlText(book.progress_text)},${sqlNumber(book.remaining_minutes)},${sqlText(book.listening_status)},1,0,${sqlText(AUDIBLE_SEED_SOURCE)},${sqlText(now)},${sqlText(now)},${sqlText(now)})`);
    statements.push(`UPDATE audible_audiobooks SET audible_product_url=COALESCE(NULLIF(audible_product_url,''),${sqlText(book.product_url)}),runtime_minutes=CASE WHEN COALESCE(runtime_minutes,0)<=0 THEN ${sqlNumber(runtime)} ELSE runtime_minutes END,runtime_display=CASE WHEN COALESCE(runtime_minutes,0)<=0 THEN ${sqlText(runtimeDisplay)} ELSE runtime_display END,description=COALESCE(NULLIF(description,''),${sqlText(book.description)}),series_id=COALESCE(series_id,${sqlText(seriesId(book))}),series_position=COALESCE(series_position,${sqlNumber(book.series_position)}),cover_image_url=CASE WHEN ${sqlText(cover)} IS NOT NULL THEN ${sqlText(cover)} ELSE cover_image_url END,cover_image_source=CASE WHEN ${sqlText(cover)} IS NOT NULL THEN ${sqlText(coverSource)} ELSE cover_image_source END,audible_progress_text=COALESCE(NULLIF(audible_progress_text,''),${sqlText(book.progress_text)}),remaining_minutes=COALESCE(remaining_minutes,${sqlNumber(book.remaining_minutes)}),listening_status=CASE WHEN COALESCE(listening_status,'unknown')='unknown' THEN ${sqlText(book.listening_status)} ELSE listening_status END,last_seen_at=${sqlText(now)} WHERE audiobook_id=${sqlText(bid)}`);
    authors.forEach((author,index)=>statements.push(`INSERT OR IGNORE INTO audible_audiobook_authors(audiobook_id,author_id,display_order) VALUES (${sqlText(bid)},${sqlText(authorId(author))},${index})`));
    (book.narrators||[]).forEach((narrator,index)=>statements.push(`INSERT OR IGNORE INTO audible_audiobook_narrators(audiobook_id,narrator_id,display_order) VALUES (${sqlText(bid)},${sqlText(narratorId(narrator))},${index})`));
  }
  return statements.join(';\n')+';';
}

export const AUDIBLE_SEED_SQL=buildAudibleSeedSql();
